{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */

import { parseInput } from './parser.js'
import { evaluateSheet } from './evaluator.js'
import { formatOutput } from './formatter.js'

const mode = process.argv[2]

if (mode !== 'values' && mode !== 'deps') {
  process.stderr.write('error: usage: cli.js values|deps\n')
  process.exit(2)
}

let input = ''
process.stdin.setEncoding('utf8')
process.stdin.on('data', chunk => {
  input += chunk
})

process.stdin.on('end', () => {
  try {
    const cells = parseInput(input)
    const sheet = evaluateSheet(cells)
    const output = formatOutput(sheet, mode)
    process.stdout.write(output)
    process.exit(0)
  } catch (error) {
    process.stderr.write(error.message + '\n')
    process.exit(2)
  }
})
"}

