{"file_path":"src/parser.js","content":"/**
 * Parse input sheet format and validate addresses.
 */

export function parseAddress(addr) {
  const match = addr.match(/^([A-Za-z]{1,2})(\d{1,3})$/)
  if (!match) return null

  const col = match[1].toUpperCase()
  const row = parseInt(match[2], 10)

  // Validate column range (A-Z, AA-ZZ)
  if (col.length === 1) {
    if (col < 'A' || col > 'Z') return null
  } else if (col.length === 2) {
    if (col < 'AA' || col > 'ZZ') return null
  }

  // Validate row range (1-999)
  if (row < 1 || row > 999) return null

  return { col, row }
}

export function addressToString(col, row) {
  return `${col}${row}`
}

export function parseInput(input) {
  const lines = input.split('\n')

  // Drop the empty tail a trailing newline leaves
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop()
  }

  const cells = new Map() // key: "A1", value: { col, row, content }

  for (let lineNum = 1; lineNum <= lines.length; lineNum++) {
    let line = lines[lineNum - 1]

    // Strip leading spaces and tabs
    line = line.replace(/^[ \t]+/, '')

    // Ignore empty lines or lines starting with #
    if (!line || line.startsWith('#')) {
      continue
    }

    // Find the address (runs to next space/tab or end of line)
    const spaceIdx = line.search(/[ \t]/)
    const addressStr = spaceIdx === -1 ? line : line.substring(0, spaceIdx)

    // Validate address
    const address = parseAddress(addressStr)
    if (!address) {
      throw new Error(`error: line ${lineNum}: invalid cell address ${addressStr}`)
    }

    const key = addressToString(address.col, address.row)

    // Check for duplicate
    if (cells.has(key)) {
      throw new Error(`error: line ${lineNum}: cell ${key} is declared twice`)
    }

    // Extract content
    let content = ''
    if (spaceIdx !== -1) {
      // Skip one run of spaces/tabs after the address
      let contentStart = spaceIdx
      while (contentStart < line.length && (line[contentStart] === ' ' || line[contentStart] === '\t')) {
        contentStart++
      }
      content = line.substring(contentStart)
    }

    cells.set(key, { col: address.col, row: address.row, content })
  }

  return cells
}
"}

