      return { type: 'lparen' }
    }
    if (ch === ')') {
      this.pos++
      return { type: 'rparen' }
    }
    if (ch === ',') {
      this.pos++
      return { type: 'comma' }
    }
    if (ch === '+') {
      this.pos++
      return { type: 'plus' }
    }
    if (ch === '-') {
      this.pos++
      return { type: 'minus' }
    }
    if (ch === '*') {
      this.pos++
      return { type: 'mul' }
    }
    if (ch === '/') {
      this.pos++
      return { type: 'div' }
    }
    if (ch === '^') {
      this.pos++
      return { type: 'pow' }
    }
    if (ch === '=') {
      this.pos++
      return { type: 'eq' }
    }
    if (ch === '<') {
      this.pos++
      if (this.pos < this.input.length && this.input[this.pos] === '=') {
