      return { type: 'lt' }
    }
    if (ch === '>') {
      this.pos++
      if (this.pos < this.input.length && this.input[this.pos] === '=') {
        this.pos++
        return { type: 'gte' }
      }
      return { type: 'gt' }
    }

    // Unknown character
    return null
  }
