      if (!p1 || !p2) return []

      const col1 = p1.col.charCodeAt(0) - 'A'.charCodeAt(0)
      const col2 = p2.col.charCodeAt(0) - 'A'.charCodeAt(0)
      let c1, c2

      if (p1.col.length === 2) {
        c1 = 26 + (p1.col.charCodeAt(1) - 'A'.charCodeAt(0))
      } else {
        c1 = col1
      }

      if (p2.col.length === 2) {
        c2 = 26 + (p2.col.charCodeAt(1) - 'A'.charCodeAt(0))
      } else {
        c2 = col2
      }

      const minC = Math.min(c1, c2)
      const maxC = Math.max(c1, c2)
      const minR = Math.min(p1.row, p2.row)
      const maxR = Math.max(p1.row, p2.row)

      const values = []
      for (let c = minC; c <= maxC; c++) {
        for (let r = minR; r <= maxR; r++) {
          const col = c < 26 ? String.fromCharCode(c + 'A'.charCodeAt(0)) : 'A' + String.fromCharCode(c - 26 + 'A'.charCodeAt(0))
          const addr = col + r
          values.push(this.evaluate(addr))
        }
      }
      return values
    }

    return [this.evaluateAst(node)]
  }

  evaluateCall(name, args) {
    if (name === 'SUM') {
      if (args.length === 0) return Value.error(ERROR_ERR)
      const values = []
      for (const arg of args) {
        const v = this.getRangeValues(arg)
        if (v.some(x => x.isError())) {
          for (const val of v) {
            if (val.isError()) return val
          }
        }
        values.push(...v)
      }
      let sum = 0
      for (const val of values) {
        const num = val.asNumber()
        if (num.isError()) return num
        sum += num.val
      }
      return Value.number(sum)
    }

    if (name === 'MIN') {
      if (args.length === 0) return Value.error(ERROR_ERR)
      let min = Infinity
      for (const arg of args) {
        const v = this.getRangeValues(arg)
        if (v.some(x => x.isError())) {
          for (const val of v) {
            if (val.isError()) return val
          }
        }
        for (const val of v) {
          const num = val.asNumber()
          if (num.isError()) return num
          min = Math.min(min, num.val)
        }
      }
      return Value.number(min === Infinity ? 0 : min)
    }

    if (name === 'MAX') {
      if (args.length === 0) return Value.error(ERROR_ERR)
      let max = -Infinity
      for (const arg of args) {
        const v = this.getRangeValues(arg)
        if (v.some(x => x.isError())) {
          for (const val of v) {
            if (val.isError()) return val
          }
        }
        for (const val of v) {
          const num = val.asNumber()
          if (num.isError()) return num
          max = Math.max(max, num.val)
        }
      }
      return Value.number(max === -Infinity ? 0 : max)
    }

    if (name === 'COUNT') {
      if (args.length === 0) return Value.error(ERROR_ERR)
      let count = 0
      for (const arg of args) {
        const v = this.getRangeValues(arg)
        for (const val of v) {
          if (val.isError()) continue
          if (val.type === 'number') count++
        }
      }
      return Value.number(count)
    }

    if (name === 'AVG') {
      if (args.length === 0) return Value.error(ERROR_ERR)
      let sum = 0
      let count = 0
      for (const arg of args) {
        const v = this.getRangeValues(arg)
        if (v.some(x => x.isError())) {
          for (const val of v) {
            if (val.isError()) return val
          }
        }
        for (const val of v) {
          const num = val.asNumber()
          if (num.isError()) return num
          sum += num.val
          count++
        }
      }
      if (count === 0) return Value.number(0)
      return Value.number(sum / count)
    }

    if (name === 'ABS') {
      if (args.length !== 1) return Value.error(ERROR_ERR)
      const val = this.evaluateAst(args[0])
      if (val.isError()) return val
      const num = val.asNumber()
      if (num.isError()) return num
      return Value.number(Math.abs(num.val))
    }

    if (name === 'IF') {
      if (args.length !== 3) return Value.error(ERROR_ERR)
      const cond = this.evaluateAst(args[0])
      if (cond.isError()) return cond
      const isTruthy = cond.type === 'boolean' ? cond.val : cond.type === 'number' ? cond.val !== 0 : true
      if (isTruthy) {
        return this.evaluateAst(args[1])
      } else {
        return this.evaluateAst(args[2])
      }
    }

    return Value.error(ERROR_NAME)
  }
}

export function evaluateSheet(cells) {
  const evaluator = new Evaluator(cells)
  const result = new Map()

  for (const [addr, cell] of cells) {
    result.set(addr, evaluator.evaluate(addr))
  }

  return result
}

export function getDependencies(cells) {
  const deps = new Map() // addr -> Set of addresses

  for (const [addr, cell] of cells) {
    const content = parseContent(cell.content)
    if (content.type === 'formula') {
      try {
        const parser = new Parser(content.formula)
        const ast = parser.parse()
        const cellDeps = new Set()
        collectDependencies(ast, cellDeps)
        deps.set(addr, cellDeps)
      } catch (e) {
        deps.set(addr, new Set())
      }
    } else {
      deps.set(addr, new Set())
    }
  }

  return deps
}

function collectDependencies(node, deps) {
  if (!node) return

  if (node.type === 'address') {
    const parsed = parseAddress(node.val)
    if (parsed) {
      const addr = addressToString(parsed.col, parsed.row)
      deps.add(addr)
    }
    return
  }

  if (node.type === 'range') {
    const p1 = parseAddress(node.addr1)
    const p2 = parseAddress(node.addr2)
    if (p1 && p2) {
      const col1 = p1.col.charCodeAt(0) - 'A'.charCodeAt(0) + (p1.col.length === 2 ? 26 : 0)
      const col2 = p2.col.charCodeAt(0) - 'A'.charCodeAt(0) + (p2.col.length === 2 ? 26 : 0)
      const minC = Math.min(col1, col2)
      const maxC = Math.max(col1, col2)
      const minR = Math.min(p1.row, p2.row)
      const maxR = Math.max(p1.row, p2.row)

      for (let c = minC; c <= maxC; c++) {
        for (let r = minR; r <= maxR; r++) {
          const col = c < 26 ? String.fromCharCode(c + 'A'.charCodeAt(0)) : 'A' + String.fromCharCode(c - 26 + 'A'.charCodeAt(0))
          const addr = col + r
          deps.add(addr)
        }
      }
    }
    return
  }

  if (node.type === 'binary' || node.type === 'comparison') {
    collectDependencies(node.left, deps)
    collectDependencies(node.right, deps)
    return
  }

  if (node.type === 'unary') {
    collectDependencies(node.expr, deps)
    return
  }

  if (node.type === 'call') {
    for (const arg of node.args) {
      collectDependencies(arg, deps)
    }
    return
  }
}
